import{_ as a,o as e,c as r,ag as i}from"./chunks/framework.DUTPmUpA.js";const h=JSON.parse('{"title":"Учебное пособие по частицам","description":"","frontmatter":{"title":"Учебное пособие по частицам","author":"Nibuja","steamId":76561198068804200,"date":"20.03.2021"},"headers":[],"relativePath":"assets/particles/particle-tutorial.md","filePath":"assets/particles/particle-tutorial.md"}'),o={name:"assets/particles/particle-tutorial.md"};function l(s,t,d,n,c,u){return e(),r("div",null,[...t[0]||(t[0]=[i('<h2 id="the-date-of-writing" tabindex="-1">The date of writing <a class="header-anchor" href="#the-date-of-writing" aria-label="Permalink to &quot;The date of writing&quot;">​</a></h2><h1 id="учебное-пособие-по-частицам" tabindex="-1">Учебное пособие по частицам <a class="header-anchor" href="#учебное-пособие-по-частицам" aria-label="Permalink to &quot;Учебное пособие по частицам&quot;">​</a></h1><p><strong>Важное примечание.</strong> <em>Эта статья тесно связана с внешним инструментом частиц и сборником руководств, и большинство ссылок направят вас туда: <a href="https://github.com/Nibuja05/dota_particle_editor_tutorial" target="_blank" rel="noreferrer">Github</a>.</em></p><p>Редактор частиц — это мощный инструмент, который позволяет создавать всевозможные эффекты частиц: от эффектов окружающей среды до снарядов и анимации HUD. Так что каждому определенно стоит научиться создавать свои собственные. Здесь вы изучите основы, необходимые для понимания этого инструмента, а также продвинутые методы, позволяющие освоить создание частиц!</p><h2 id="как-начать" tabindex="-1">Как начать? <a class="header-anchor" href="#как-начать" aria-label="Permalink to &quot;Как начать?&quot;">​</a></h2><p>Этот проект должен помочь вам найти свой путь в мир эффектов частиц. Для этого имеется несколько документов:</p><ul><li><a href="https://github.com/Nibuja05/dota_particle_editor_tutorial/blob/master/Particle%20Editor%20Guide.md" target="_blank" rel="noreferrer">Particle Editor Guide</a>, который содержит подробную информацию обо всех возможных областях редактора частиц и поэтому может использоваться как в качестве введения, так и в качестве справочного руководства.</li><li><a href="https://github.com/Nibuja05/dota_particle_editor_tutorial/blob/master/Tutorials.md" target="_blank" rel="noreferrer">Tutorials Page</a> — сборник пошаговых руководств для начинающих, а также решения некоторых более глубоких и сложных задач.</li><li><a href="https://github.com/Nibuja05/dota_particle_editor_tutorial/blob/master/Function%20Library.md" target="_blank" rel="noreferrer">Function Library</a>, коллекция всех известных функций с описанием их использования и другой полезной информацией.</li></ul><p>Если вы новичок в этой теме, рекомендуется начать читать разделы Руководства по редактору частиц <code>The Tool</code> и <code>Functions</code>. После этого следуйте некоторым базовым руководствам со страницы учебных пособий.</p>',8)])])}const p=a(o,[["render",l]]);export{h as __pageData,p as default};
